-- Durable paired packet identity and per-encounter/source/run processing state.
CREATE TABLE simulation_sources(source_id text NOT NULL, encounter_id text NOT NULL REFERENCES encounters(id), enabled boolean NOT NULL DEFAULT true, PRIMARY KEY(source_id,encounter_id));
CREATE TABLE simulation_streams(source_id text NOT NULL, encounter_id text NOT NULL, run_id text NOT NULL, time_scale float8 NOT NULL CHECK(time_scale>=1 AND time_scale<=600), last_observed_at timestamptz, last_received_at timestamptz, chest_roll float8, pelvis_roll float8, chest_anchor float8, pelvis_anchor float8, chest_time timestamptz, pelvis_time timestamptz, last_candidate_at timestamptz, PRIMARY KEY(source_id,encounter_id,run_id), FOREIGN KEY(source_id,encounter_id) REFERENCES simulation_sources(source_id,encounter_id));
CREATE TABLE ingestion_receipts(sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE, id text PRIMARY KEY, source_id text NOT NULL, encounter_id text NOT NULL, run_id text NOT NULL, event_id text NOT NULL, content_hash text NOT NULL, observed_at timestamptz NOT NULL, received_at timestamptz NOT NULL, processed_at timestamptz NOT NULL, processing_status text NOT NULL, movement_id text REFERENCES movement_candidates(id) DEFERRABLE INITIALLY DEFERRED, UNIQUE(source_id,encounter_id,run_id,event_id), FOREIGN KEY(source_id,encounter_id,run_id) REFERENCES simulation_streams(source_id,encounter_id,run_id));
CREATE TABLE raw_imu_samples(id text PRIMARY KEY, receipt_id text NOT NULL REFERENCES ingestion_receipts(id), encounter_id text NOT NULL REFERENCES encounters(id), device_id text NOT NULL REFERENCES devices(id), body_region text NOT NULL CHECK(body_region IN ('UPPER_TORSO','PELVIS')), ax float8 NOT NULL, ay float8 NOT NULL, az float8 NOT NULL, gx float8 NOT NULL, gy float8 NOT NULL, gz float8 NOT NULL, observed_at timestamptz NOT NULL, received_at timestamptz NOT NULL, processed_at timestamptz NOT NULL, quality text NOT NULL, source_time text NOT NULL, derived_sample_id text REFERENCES orientation_samples(id) DEFERRABLE INITIALLY DEFERRED, UNIQUE(receipt_id,body_region));
CREATE INDEX raw_imu_history ON raw_imu_samples(encounter_id,observed_at,id);
CREATE INDEX raw_imu_delta ON raw_imu_samples(encounter_id,received_at,id);
ALTER TABLE devices ADD COLUMN time_domain text NOT NULL DEFAULT 'WALL_CLOCK';
ALTER TABLE devices ADD COLUMN last_source_at timestamptz;
ALTER TABLE devices ADD COLUMN simulation_scale float8 NOT NULL DEFAULT 1;
CREATE INDEX ingestion_receipt_delta ON ingestion_receipts(encounter_id,received_at,id);
